@dp.table(name="claims_summary_gold")
def claims_summary_gold():
    claims = dp.read("claims_clean")
    return claims.groupBy("clinic_id", "claim_date").agg(
        _sum("claim_amount_usd").alias("total_billed_usd"),
        _count("claim_id").alias("claim_count"),
        (_sum(col("denial_flag").cast("int")) / _count("claim_id"))
            .alias("denial_rate"))

@dp.table(name="claims_detail_gold")
def claims_detail_gold():
    return dp.read("claims_clean").select(
        "claim_id", "clinic_id", "patient_id",
        "patient_name", "patient_ssn",
        "claim_date", "claim_amount_usd", "denial_flag")

